// Get skill parameters
const params = $input.first().json.parameters;
const searchType = params.search_type;
const query = params.query || '';

// Build API URL
let url;

switch(searchType) {
  case 'name':
    url = `search.php?s=${encodeURIComponent(query)}`;
    break;
  case 'ingredient':
    url = `filter.php?i=${encodeURIComponent(query)}`;
    break;
  case 'category':
    url = `filter.php?c=${encodeURIComponent(query)}`;
    break;
  case 'area':
    url = `filter.php?a=${encodeURIComponent(query)}`;
    break;
  case 'random':
    url = 'random.php';
    break;
  default:
    throw new Error(`Invalid search_type: ${searchType}`);
}

return [{
  json: {
    url: `https://www.themealdb.com/api/json/v1/1/${url}`,
    max_results: params.max_results || 10
  }
}];

const response = $input.first().json;
const maxResults = $('convert parameters to url').first().json.max_results;

// Extract meals array
const meals = response.meals || [];

// Limit results BEFORE mapping
const limitedMeals = meals.slice(0, maxResults);

// Format for AI
const formattedRecipes = limitedMeals.map(meal => {
  // Build ingredients array
  const ingredients = [];
  for (let i = 1; i <= 20; i++) {
    const ingredient = meal[`strIngredient${i}`];
    const measure = meal[`strMeasure${i}`];
    if (ingredient && ingredient.trim()) {
      ingredients.push({
        name: ingredient,
        measurement: measure ? measure.trim() : ''
      });
    }
  }

  return {
    name: meal.strMeal,
    id: meal.idMeal,
    category: meal.strCategory,
    area: meal.strArea,
    thumbnail: meal.strMealThumb,
    instructions: meal.strInstructions,
    ingredients: ingredients,
    youtube: meal.strYoutube || null,
    source: meal.strSource || null
  };
});

return [{
  json: {
    recipes: formattedRecipes,
    count: formattedRecipes.length
  }
}];
